package com.example.starter.maintenance.model;

/**
 * 设备：保养周期登记后不可改；version 为乐观锁版本，每次成功写操作加一。
 *
 * @param equipmentId               设备唯一标识
 * @param maintenanceIntervalMinutes 保养周期，单位分钟，正整数
 * @param version                   设备版本，初始1
 */
public record Equipment(String equipmentId, int maintenanceIntervalMinutes, int version) {
}

package com.example.starter.maintenance.model;

import java.time.Instant;

/**
 * 工时读数：设备内 readingId 唯一，同设备同一采样时刻仅一条。
 *
 * @param readingId          设备内唯一读数标识
 * @param sampledAt          UTC 采样时刻
 * @param accumulatedMinutes 当前累计工时，单位分钟，非负整数
 * @param currentRevision    当前修订号，初始1
 */
public record Reading(String readingId, Instant sampledAt, long accumulatedMinutes, int currentRevision) {
}

package com.example.starter.maintenance.model;

import java.time.Instant;

/**
 * 读数修订历史条目：修订只改变累计分钟，不改采样时刻。
 *
 * @param revisionNo         修订号，从1开始单调递增
 * @param accumulatedMinutes 该修订版本的累计工时，单位分钟
 * @param revisedAt          修订发生时刻（UTC）
 */
public record ReadingRevision(int revisionNo, long accumulatedMinutes, Instant revisedAt) {
}

package com.example.starter.maintenance.model;

import java.time.Instant;

/**
 * 保养记录：保存锚点读数及其工时快照，不允许删除。
 *
 * @param maintenanceId           保养记录自增主键
 * @param anchorReadingId         锚点读数标识
 * @param anchorRevisionNo        完成保养时锚点读数的当前修订号
 * @param anchorSampledAt         锚点读数采样时刻（UTC）
 * @param anchorAccumulatedMinutes 完成保养时锚点读数累计工时快照，单位分钟
 * @param completedAt             保养完成时刻（UTC）
 */
public record MaintenanceRecord(long maintenanceId, String anchorReadingId, int anchorRevisionNo,
                                Instant anchorSampledAt, long anchorAccumulatedMinutes, Instant completedAt) {
}

package com.example.starter.maintenance.web;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码，由全局异常处理器转换为错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    public static ApiException unprocessable(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

