package com.example.starter.maintenance.repository;

import com.example.starter.maintenance.model.Equipment;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * 设备表数据访问。
 */
@Repository
public class EquipmentRepository {

    private final JdbcTemplate jdbc;

    public EquipmentRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(String equipmentId, int intervalMinutes, long nowEpochMs) {
        jdbc.update("INSERT INTO equipment (equipment_id, maintenance_interval_minutes, version, created_at_epoch_ms)"
                        + " VALUES (?, ?, 1, ?)",
                equipmentId, intervalMinutes, nowEpochMs);
    }

    public Optional<Equipment> findById(String equipmentId) {
        return jdbc.query("SELECT equipment_id, maintenance_interval_minutes, version FROM equipment WHERE equipment_id = ?",
                (rs, i) -> new Equipment(rs.getString(1), rs.getInt(2), rs.getInt(3)),
                equipmentId).stream().findFirst();
    }

    /**
     * 加行锁读取设备，串行化同一设备的写操作，配合版本校验避免并发冲突。
     */
    public Optional<Equipment> findByIdForUpdate(String equipmentId) {
        return jdbc.query("SELECT equipment_id, maintenance_interval_minutes, version FROM equipment"
                        + " WHERE equipment_id = ? FOR UPDATE",
                (rs, i) -> new Equipment(rs.getString(1), rs.getInt(2), rs.getInt(3)),
                equipmentId).stream().findFirst();
    }

    public void incrementVersion(String equipmentId) {
        jdbc.update("UPDATE equipment SET version = version + 1 WHERE equipment_id = ?", equipmentId);
    }
}

package com.example.starter.maintenance.repository;

import com.example.starter.maintenance.model.Reading;
import com.example.starter.maintenance.model.ReadingRevision;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * 工时读数及修订历史数据访问。
 */
@Repository
public class ReadingRepository {

    private final JdbcTemplate jdbc;

    public ReadingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static Reading mapReading(java.sql.ResultSet rs, int i) throws java.sql.SQLException {
        return new Reading(rs.getString("reading_id"),
                Instant.ofEpochMilli(rs.getLong("sampled_at_epoch_ms")),
                rs.getLong("accumulated_minutes"),
                rs.getInt("current_revision"));
    }

    public void insert(String equipmentId, String readingId, long sampledAtEpochMs,
                       long accumulatedMinutes, long nowEpochMs) {
        jdbc.update("INSERT INTO equipment_reading"
                        + " (equipment_id, reading_id, sampled_at_epoch_ms, accumulated_minutes, current_revision, created_at_epoch_ms)"
                        + " VALUES (?, ?, ?, ?, 1, ?)",
                equipmentId, readingId, sampledAtEpochMs, accumulatedMinutes, nowEpochMs);
    }

    public Optional<Reading> findById(String equipmentId, String readingId) {
        return jdbc.query("SELECT reading_id, sampled_at_epoch_ms, accumulated_minutes, current_revision"
                        + " FROM equipment_reading WHERE equipment_id = ? AND reading_id = ?",
                ReadingRepository::mapReading, equipmentId, readingId).stream().findFirst();
    }

    public boolean existsBySampledAt(String equipmentId, long sampledAtEpochMs) {
        Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM equipment_reading"
                + " WHERE equipment_id = ? AND sampled_at_epoch_ms = ?", Integer.class, equipmentId, sampledAtEpochMs);
        return count != null && count > 0;
    }

    /**
     * 采样时刻严格早于给定时刻的最近一条读数（前邻）。
     */
    public Optional<Reading> findPrevious(String equipmentId, long sampledAtEpochMs) {
        return jdbc.query("SELECT reading_id, sampled_at_epoch_ms, accumulated_minutes, current_revision"
                        + " FROM equipment_reading WHERE equipment_id = ? AND sampled_at_epoch_ms < ?"
                        + " ORDER BY sampled_at_epoch_ms DESC LIMIT 1",
                ReadingRepository::mapReading, equipmentId, sampledAtEpochMs).stream().findFirst();
    }

    /**
     * 采样时刻严格晚于给定时刻的最近一条读数（后邻）。
     */
    public Optional<Reading> findNext(String equipmentId, long sampledAtEpochMs) {
        return jdbc.query("SELECT reading_id, sampled_at_epoch_ms, accumulated_minutes, current_revision"
                        + " FROM equipment_reading WHERE equipment_id = ? AND sampled_at_epoch_ms > ?"
                        + " ORDER BY sampled_at_epoch_ms ASC LIMIT 1",
                ReadingRepository::mapReading, equipmentId, sampledAtEpochMs).stream().findFirst();
    }

    public List<Reading> findAllByEquipment(String equipmentId) {
        return jdbc.query("SELECT reading_id, sampled_at_epoch_ms, accumulated_minutes, current_revision"
                        + " FROM equipment_reading WHERE equipment_id = ? ORDER BY sampled_at_epoch_ms ASC",
                ReadingRepository::mapReading, equipmentId);
    }

    public Optional<Reading> findLatest(String equipmentId) {
        return jdbc.query("SELECT reading_id, sampled_at_epoch_ms, accumulated_minutes, current_revision"
                        + " FROM equipment_reading WHERE equipment_id = ?"
                        + " ORDER BY sampled_at_epoch_ms DESC LIMIT 1",
                ReadingRepository::mapReading, equipmentId).stream().findFirst();
    }

    /**
     * 修订：仅更新累计分钟并递增修订号。
     */
    public void updateAccumulatedMinutes(String equipmentId, String readingId, long accumulatedMinutes) {
        jdbc.update("UPDATE equipment_reading SET accumulated_minutes = ?, current_revision = current_revision + 1"
                + " WHERE equipment_id = ? AND reading_id = ?", accumulatedMinutes, equipmentId, readingId);
    }

    public void insertRevision(String equipmentId, String readingId, int revisionNo,
                               long accumulatedMinutes, long revisedAtEpochMs) {
        jdbc.update("INSERT INTO reading_revision"
                        + " (equipment_id, reading_id, revision_no, accumulated_minutes, revised_at_epoch_ms)"
                        + " VALUES (?, ?, ?, ?, ?)",
                equipmentId, readingId, revisionNo, accumulatedMinutes, revisedAtEpochMs);
    }

    public List<ReadingRevision> findRevisions(String equipmentId, String readingId) {
        return jdbc.query("SELECT revision_no, accumulated_minutes, revised_at_epoch_ms FROM reading_revision"
                        + " WHERE equipment_id = ? AND reading_id = ? ORDER BY revision_no ASC",
                (rs, i) -> new ReadingRevision(rs.getInt(1), rs.getLong(2), Instant.ofEpochMilli(rs.getLong(3))),
                equipmentId, readingId);
    }
}

package com.example.starter.maintenance.repository;

import com.example.starter.maintenance.model.MaintenanceRecord;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * 保养记录数据访问；只增不删。
 */
@Repository
public class MaintenanceRepository {

    private final JdbcTemplate jdbc;

    public MaintenanceRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static MaintenanceRecord map(ResultSet rs, int i) throws SQLException {
        return new MaintenanceRecord(rs.getLong("maintenance_id"),
                rs.getString("anchor_reading_id"),
                rs.getInt("anchor_revision_no"),
                Instant.ofEpochMilli(rs.getLong("anchor_sampled_at_epoch_ms")),
                rs.getLong("anchor_accumulated_minutes"),
                Instant.ofEpochMilli(rs.getLong("completed_at_epoch_ms")));
    }

    public void insert(String equipmentId, String anchorReadingId, int anchorRevisionNo,
                       long anchorSampledAtEpochMs, long anchorAccumulatedMinutes, long completedAtEpochMs) {
        jdbc.update("INSERT INTO maintenance_record"
                        + " (equipment_id, anchor_reading_id, anchor_revision_no,"
                        + " anchor_sampled_at_epoch_ms, anchor_accumulated_minutes, completed_at_epoch_ms)"
                        + " VALUES (?, ?, ?, ?, ?, ?)",
                equipmentId, anchorReadingId, anchorRevisionNo,
                anchorSampledAtEpochMs, anchorAccumulatedMinutes, completedAtEpochMs);
    }

    /**
     * 最近一次保养（按锚点采样时刻，其次按主键）。
     */
    public Optional<MaintenanceRecord> findLatest(String equipmentId) {
        return jdbc.query("SELECT maintenance_id, anchor_reading_id, anchor_revision_no,"
                        + " anchor_sampled_at_epoch_ms, anchor_accumulated_minutes, completed_at_epoch_ms"
                        + " FROM maintenance_record WHERE equipment_id = ?"
                        + " ORDER BY anchor_sampled_at_epoch_ms DESC, maintenance_id DESC LIMIT 1",
                MaintenanceRepository::map, equipmentId).stream().findFirst();
    }

    public List<MaintenanceRecord> findAllByEquipment(String equipmentId) {
        return jdbc.query("SELECT maintenance_id, anchor_reading_id, anchor_revision_no,"
                        + " anchor_sampled_at_epoch_ms, anchor_accumulated_minutes, completed_at_epoch_ms"
                        + " FROM maintenance_record WHERE equipment_id = ?"
                        + " ORDER BY anchor_sampled_at_epoch_ms ASC, maintenance_id ASC",
                MaintenanceRepository::map, equipmentId);
    }

    /**
     * 指定读数是否作为任意历史保养锚点。
     */
    public boolean isAnchorOfAnyMaintenance(String equipmentId, String readingId) {
        Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM maintenance_record"
                        + " WHERE equipment_id = ? AND anchor_reading_id = ?",
                Integer.class, equipmentId, readingId);
        return count != null && count > 0;
    }
}

package com.example.starter.maintenance.repository;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * 幂等键数据访问；仅成功写操作占键，与业务变更同事务提交。
 */
@Repository
public class IdempotencyRepository {

    /**
     * 已占键记录快照。
     *
     * @param action         操作类型
     * @param payloadHash    规范化请求参数摘要
     * @param responseStatus 原成功响应状态码
     * @param responseBody   原成功响应体
     */
    public record Entry(String action, String payloadHash, int responseStatus, String responseBody) {
    }

    private final JdbcTemplate jdbc;

    public IdempotencyRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Optional<Entry> find(String requestId) {
        return jdbc.query("SELECT action, payload_hash, response_status, response_body FROM idempotency_key"
                        + " WHERE request_id = ?",
                (rs, i) -> new Entry(rs.getString(1), rs.getString(2), rs.getInt(3), rs.getString(4)),
                requestId).stream().findFirst();
    }

    public void insert(String requestId, String action, String payloadHash,
                       int responseStatus, String responseBody, long nowEpochMs) {
        jdbc.update("INSERT INTO idempotency_key (request_id, action, payload_hash, response_status, response_body, created_at_epoch_ms)"
                        + " VALUES (?, ?, ?, ?, ?, ?)",
                requestId, action, payloadHash, responseStatus, responseBody, nowEpochMs);
    }
}

